#[derive(Debug, Clone, PartialEq)]
pub enum JobInfo {
    Shell(JobShell),
    Subagent(JobSubagent),
    Image(JobImage),
    Video(JobVideo),
    Codemode(JobCodeMode),
}

impl crate::codec::Decode for JobInfo {
    fn decode(value: &Value, path: &mut crate::codec::Path) -> Result<Self, crate::codec::DecodeError> {
        let object = crate::codec::as_object(value, path)?;
        let tag: String = crate::codec::decode_field(object, "kind", path)?;
        match tag.as_str() {
            "shell" => <JobShell as crate::codec::Decode>::decode(value, path).map(Self::Shell),
            "subagent" => <JobSubagent as crate::codec::Decode>::decode(value, path).map(Self::Subagent),
            "image" => <JobImage as crate::codec::Decode>::decode(value, path).map(Self::Image),
            "video" => <JobVideo as crate::codec::Decode>::decode(value, path).map(Self::Video),
            "codemode" => <JobCodeMode as crate::codec::Decode>::decode(value, path).map(Self::Codemode),
            _ => Err(path.at("expected a known kind")),
        }
    }
}

impl crate::codec::Encode for JobInfo {
    fn encode(&self, out: &mut String) {
        match self {
            Self::Shell(value) => <JobShell as crate::codec::Encode>::encode(value, out),
            Self::Subagent(value) => <JobSubagent as crate::codec::Encode>::encode(value, out),
            Self::Image(value) => <JobImage as crate::codec::Encode>::encode(value, out),
            Self::Video(value) => <JobVideo as crate::codec::Encode>::encode(value, out),
            Self::Codemode(value) => <JobCodeMode as crate::codec::Encode>::encode(value, out),
        }
    }
}

