        if let Ok(member) = <f64 as crate::codec::Decode>::decode(value, path) {
            return Ok(Self::Number(member));
        }
        if let Ok(member) = <bool as crate::codec::Decode>::decode(value, path) {
            return Ok(Self::Bool(member));
        }
